<?php
namespace ExcelHerbal\ERP7\Security;
use ExcelHerbal\ERP7\Database\Db;
use ExcelHerbal\ERP7\Database\Transaction;
use ExcelHerbal\ERP7\Domain\DomainException;
final class MobileAuth{
 private const ACCESS_TTL=3600; private const REFRESH_TTL=2592000;
 public static function boot():void{add_filter('determine_current_user',[self::class,'user'],20);}
 public static function user($current){if($current)return$current;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer\s+(.+)$/i',$h,$m))return$current;$hash=hash('sha256',trim($m[1]));$db=Db::wpdb();$t=Db::table('mobile_sessions');$now=gmdate('Y-m-d H:i:s');$row=$db->get_row($db->prepare("SELECT id,wp_user_id FROM {$t} WHERE access_hash=%s AND revoked_at IS NULL AND access_expires_at>%s LIMIT 1",$hash,$now),ARRAY_A);if(!$row)return$current;$db->update($t,['last_used_at'=>$now],['id'=>(int)$row['id']]);return(int)$row['wp_user_id'];}
 public static function login(string $mobile,string $password,string $device=''):array{$mobile=preg_replace('/\D+/','',$mobile);if($mobile===''||$password==='')throw new DomainException('Mobile number and password are required.','credentials_required',422);$db=Db::wpdb();$e=Db::table('employees');$candidates=(array)$db->get_results("SELECT * FROM {$e} WHERE status='active' AND wp_user_id IS NOT NULL AND mobile IS NOT NULL",ARRAY_A);$rows=[];foreach($candidates as$c){$stored=preg_replace('/\D+/','',(string)$c['mobile']);if($stored===$mobile)$rows[]=$c;}if(count($rows)!==1)throw new DomainException('Invalid login credentials.','invalid_credentials',401);$emp=$rows[0];if(!(int)$emp['wp_user_id'])throw new DomainException('Invalid login credentials.','invalid_credentials',401);$u=get_user_by('id',(int)$emp['wp_user_id']);if(!$u||!wp_check_password($password,$u->user_pass,(int)$u->ID))throw new DomainException('Invalid login credentials.','invalid_credentials',401);return self::issue((int)$u->ID,(int)$emp['id'],$device);}
 public static function refresh(string $refresh,string $device=''):array{if(trim($refresh)==='')throw new DomainException('Refresh token required.','refresh_required',422);return Transaction::run(function()use($refresh,$device){$db=Db::wpdb();$t=Db::table('mobile_sessions');$hash=hash('sha256',$refresh);$now=gmdate('Y-m-d H:i:s');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE refresh_hash=%s AND revoked_at IS NULL AND refresh_expires_at>%s LIMIT 1 FOR UPDATE",$hash,$now),ARRAY_A);if(!$r)throw new DomainException('Refresh token invalid or expired.','refresh_invalid',401);$db->update($t,['revoked_at'=>$now],['id'=>(int)$r['id']]);return self::issue((int)$r['wp_user_id'],(int)$r['employee_id'],$device?:($r['device_name']??''));});}
 public static function logout():array{$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(preg_match('/^Bearer\s+(.+)$/i',$h,$m))Db::wpdb()->update(Db::table('mobile_sessions'),['revoked_at'=>gmdate('Y-m-d H:i:s')],['access_hash'=>hash('sha256',trim($m[1]))]);return['logged_out'=>true];}
 private static function issue(int $uid,int $eid,string $device):array{$access=bin2hex(random_bytes(32));$refresh=bin2hex(random_bytes(48));$now=time();$db=Db::wpdb();Db::mustInsert($db,Db::table('mobile_sessions'),['wp_user_id'=>$uid,'employee_id'=>$eid,'access_hash'=>hash('sha256',$access),'refresh_hash'=>hash('sha256',$refresh),'access_expires_at'=>gmdate('Y-m-d H:i:s',$now+self::ACCESS_TTL),'refresh_expires_at'=>gmdate('Y-m-d H:i:s',$now+self::REFRESH_TTL),'device_name'=>substr(trim($device),0,190),'created_at'=>gmdate('Y-m-d H:i:s')]);if(!$db->insert_id)throw new DomainException('Unable to create mobile session.','session_create_failed',500);return['access_token'=>$access,'refresh_token'=>$refresh,'token_type'=>'Bearer','expires_in'=>self::ACCESS_TTL];}
}
